function clampAudio(v,def){const n=Number(v);return Math.max(0,Math.min(100,Number.isFinite(n)?n:def))}
function sfxVolume(){return clampAudio(localStorage.sosoSfxVolume,20)/100}
function bgmVolume(){return clampAudio(localStorage.sosoBgmVolume,10)/100}
function narrationVolume(){return clampAudio(localStorage.sosoNarrationVolume,85)/100}
