function ac(){return audioCtx||(audioCtx=new(window.AudioContext||window.webkitAudioContext)())}
function tone(freq=440,dur=.09,type='sine',vol=.055,delay=0){if(!soundOn)return;try{const c=ac(),o=c.createOscillator(),g=c.createGain(),t=c.currentTime+delay;o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(vol*sfxVolume(),t);g.gain.exponentialRampToValueAtTime(.001,t+dur);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+dur)}catch{}}
function playSfx(k){if(!soundOn)return;if(k==='click')tone(520,.045,'sine',.025);if(k==='start'){tone(392,.08);tone(523,.1,'sine',.05,.09);tone(659,.13,'sine',.05,.18)}if(k==='night'){tone(220,.28,'sine',.05);tone(164,.35,'sine',.035,.12)}if(k==='day'){tone(523,.1);tone(659,.1,'sine',.05,.1);tone(784,.18,'sine',.05,.2)}if(k==='gun'){tone(85,.08,'square',.12);tone(48,.18,'sawtooth',.08,.04)}if(k==='role'){tone(110,.34,'sine',.07);tone(165,.34,'sine',.06,.16);tone(330,.18,'triangle',.07,.55);tone(494,.26,'sine',.065,.72)}if(k==='vote'){tone(740,.06);tone(880,.08,'sine',.04,.08)}if(k==='win'){tone(523,.08);tone(659,.08,'sine',.05,.09);tone(784,.08,'sine',.05,.18);tone(1047,.22,'sine',.06,.27)}if(k==='warning'){tone(920,.08,'square',.04);tone(760,.08,'square',.035,.12)}}
