const mafiaNightBgm=new Audio('/mafia-night.mp3'),mafiaDayBgm=new Audio('/mafia-day.mp3'),mafiaVoteBgm=new Audio('/mafia-vote.mp3'),mafiaGunSfx=new Audio('/mafia-gun.mp3');
[mafiaNightBgm,mafiaDayBgm,mafiaVoteBgm].forEach(a=>a.loop=true);
let lastMafiaDealer='';
function mafiaStopAudio(){[mafiaNightBgm,mafiaDayBgm,mafiaVoteBgm].forEach(a=>{a.pause();a.currentTime=0})}
function mafiaPlayGun(){if(!soundOn)return;try{mafiaGunSfx.currentTime=Math.min(.5,mafiaGunSfx.duration||.5);mafiaGunSfx.volume=sfxVolume();mafiaGunSfx.play().catch(()=>{})}catch{}}
function speakMafiaDealer(text){if(!text)return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ko-KR';u.rate=1.42;u.pitch=.88;u.volume=narrationOn?narrationVolume():0;speechSynthesis.speak(u)}catch{}}
function syncMafiaAudio(){
  if(!state||state.game!=='mafia'){mafiaStopAudio();return}
  const base=bgmVolume();[mafiaNightBgm,mafiaDayBgm,mafiaVoteBgm].forEach(a=>a.volume=base);
  if(!bgmOn){mafiaStopAudio()}else{
    const target=state.phase==='mafiaNight'?mafiaNightBgm:(['mafiaVote','mafiaDefense','mafiaExecuteVote','terroristPick'].includes(state.phase)?mafiaVoteBgm:(state.phase==='mafiaDay'?mafiaDayBgm:null));
    [mafiaNightBgm,mafiaDayBgm,mafiaVoteBgm].forEach(a=>{if(a!==target)a.pause()});
    if(target&&target.paused)target.play().catch(()=>{});
  }
  
}

