let geniusProfile=null,pendingGeniusAction=null;function selectGenius(){game='genius';$$('.game').forEach(x=>x.classList.toggle('active',x.id==='geniusOpen'));toast('💎 지니어스게임 방을 선택했습니다.')}function selectDeathmatch(btn=document.querySelector('.game[data-game="deathmatch"]')){game='deathmatch';$$('.game').forEach(x=>x.classList.toggle('active',x===btn));toast('데스매치를 선택했습니다.')}function openGeniusAuth(action=null){pendingGeniusAction=action;$('#geniusModal').classList.remove('hidden');if(geniusProfile){$('#geniusLogin').classList.add('hidden');$('#geniusLogged').classList.remove('hidden');$('#geniusProfile').innerHTML=`<b>${esc(geniusProfile.name)}</b><span>💎 보유 가넷 ${geniusProfile.garnets} · 🏆 우승 ${geniusProfile.wins}회</span>`}else{$('#geniusLogin').classList.remove('hidden');$('#geniusLogged').classList.add('hidden')}}$('#geniusOpen').onclick=()=>{if(geniusProfile)selectGenius();else openGeniusAuth('select')};$('#geniusClose').onclick=()=>{$('#geniusModal').classList.add('hidden');pendingGeniusAction=null};$('#geniusLoginBtn').onclick=()=>socket.emit('geniusAuth',{name:$('#geniusName').value,password:$('#geniusPassword').value},r=>{if(!r.ok)return toast(r.error);geniusProfile=r.profile;$('#geniusProfile').innerHTML=`<b>${esc(r.profile.name)}</b><span>💎 보유 가넷 ${r.profile.garnets} · 🏆 우승 ${r.profile.wins}회</span>`;$('#geniusHomeProfile').classList.remove('hidden');$('#geniusHomeProfile').innerHTML=`<b>💎 ${esc(r.profile.name)}</b><span>가넷 ${r.profile.garnets} · 우승 ${r.profile.wins}회</span>`;$('#geniusLogin').classList.add('hidden');$('#geniusLogged').classList.remove('hidden');const a=pendingGeniusAction;pendingGeniusAction=null;if(['selectDeathmatch','createDeathmatch'].includes(a))selectDeathmatch();else if(a!=='join')selectGenius();$('#geniusModal').classList.add('hidden');if(a==='create'||a==='createDeathmatch')setTimeout(()=>$('#createBtn').click(),50);if(a==='join')setTimeout(()=>$('#joinBtn').click(),50)});
