function initRummiDraft(){if(!state?.rummi||!priv?.rack)return;rDraft={board:(state.rummi.board||[]).map(g=>g.map(t=>({...t}))),rack:(priv.rack||[]).map(t=>({...t}))};selectedTile=null}
function tileHtml(t,source,group=''){if(!t)return '';const cls=t.joker?'joker':(t.color||'black');const label=t.joker?'JOKER':t.n;return `<div class="tile ${cls}" data-tile="${esc(t.id)}" data-source="${source}" ${source==='board'?`data-group="${group}"`:''}><span>${label}</span></div>`}
function renderRummi(){if(!state.rummi){$('#mainCard').innerHTML='<div class="big">루미큐브 준비 중…</div>';$('#actionArea').innerHTML='';return}if(!priv){$('#mainCard').innerHTML='<div class="big">내 타일을 불러오는 중…</div>';$('#actionArea').innerHTML='<div class="rummi-table rummi-table-loading">테이블을 준비하고 있습니다.</div>';return}if(!rDraft)initRummiDraft();const r=state.rummi,myTurn=r.turnPlayerId===me,turnP=state.players.find(p=>p.id===r.turnPlayerId);$('#mainCard').innerHTML=`<div class="rummi-turnline"><strong class="${myTurn?'turn-me':''}">${myTurn?'👉 내 차례':`⏳ ${esc(turnP?.name||'')}님 차례`}</strong><div class="rummi-info"><span class="info-chip">턴 ${r.turnNumber}</span><span class="info-chip">남은 타일 ${r.poolCount}</span><span class="info-chip">${priv.registered?'✅ 등록 완료':'🎯 첫 등록 30점'}</span></div></div>${r.lastAction?`<div class="rummi-last-action">${esc(r.lastAction)}</div>`:''}`;const board=rDraft?.board||r.board,rack=rDraft?.rack||priv.rack;$('#actionArea').innerHTML=`<div class="rummi-section-head"><h3>테이블</h3><span class="muted">조합을 드래그해 배치하세요</span></div><div id="rTable" class="rummi-table">${board.map((g,i)=>`<div class="rummi-group" data-drop="group" data-group="${i}">${g.map(t=>tileHtml(t,'board',i)).join('')}</div>`).join('')}<div class="rummi-group rummi-new" data-drop="new">＋ 새 조합</div></div><div class="rummi-rack-head"><h3>내 패 · ${rack.length}개</h3><div class="rummi-controls"><button id="sortColor">같은 색끼리</button><button id="sortAsc">숫자 ↑</button><button id="sortDesc">숫자 ↓</button>${myTurn?'<button id="resetDraft">↺ 배치 취소</button><button id="drawTile">타일 1개 가져오기</button><button id="commit" class="primary compact">✅ 턴 완료</button>':''}</div></div><div id="rack" class="rack" data-drop="rack">${rack.map(t=>tileHtml(t,'rack')).join('')}</div><p class="muted rummi-help">PC: 드래그앤드롭 · 모바일: 타일을 끌어서 원하는 조합에 놓으세요. 테이블 타일도 내 차례에는 재배치할 수 있습니다.</p>`;bindRummiUI(myTurn)}
function bindRummiUI(myTurn){$('#sortColor').onclick=()=>{rDraft.rack.sort((a,b)=>a.color.localeCompare(b.color)||a.n-b.n);renderRummi()};$('#sortAsc').onclick=()=>{rDraft.rack.sort((a,b)=>(a.joker?99:a.n)-(b.joker?99:b.n)||a.color.localeCompare(b.color));renderRummi()};$('#sortDesc').onclick=()=>{rDraft.rack.sort((a,b)=>(b.joker?99:b.n)-(a.joker?99:a.n)||a.color.localeCompare(b.color));renderRummi()};if($('#resetDraft'))$('#resetDraft').onclick=()=>{initRummiDraft();renderRummi()};if($('#drawTile'))$('#drawTile').onclick=()=>socket.emit('rummiDraw',{},r=>{if(!r.ok)toast(r.error)});if($('#commit'))$('#commit').onclick=()=>socket.emit('rummiCommit',{board:rDraft.board.map(g=>g.map(t=>t.id)),rackIds:rDraft.rack.map(t=>t.id)},r=>{if(!r.ok)toast(r.error);else rDraft=null});$$('.tile').forEach(t=>{if(!myTurn)return;t.onpointerdown=startTileDrag;t.onclick=()=>{selectedTile={id:t.dataset.tile,source:t.dataset.source,group:+t.dataset.group};toast('타일 선택됨 · 놓을 위치를 누르세요.')}});$$('[data-drop]').forEach(z=>{z.onclick=e=>{if(!myTurn||!selectedTile||e.target.classList.contains('tile'))return;moveRummiTile(selectedTile,z.dataset.drop,+z.dataset.group);selectedTile=null};z.onpointerup=e=>{if(dragData){moveRummiTile(dragData,z.dataset.drop,+z.dataset.group);endTileDrag()}}})}
let dragData=null,dragMove=null,dragUp=null;
function startTileDrag(e){e.preventDefault();const el=e.currentTarget;dragData={id:el.dataset.tile,source:el.dataset.source,group:+el.dataset.group};dragGhost=el.cloneNode(true);dragGhost.style.cssText='position:fixed;z-index:50;pointer-events:none;opacity:.85;transform:scale(1.08);';document.body.appendChild(dragGhost);moveGhost(e.clientX,e.clientY);dragMove=ev=>moveGhost(ev.clientX,ev.clientY);dragUp=ev=>{const raw=document.elementFromPoint(ev.clientX,ev.clientY);const tileHit=raw?.closest('.tile');if(tileHit&&tileHit.dataset.source==='rack'&&dragData.source==='rack'&&tileHit.dataset.tile!==dragData.id){reorderRackTile(dragData.id,tileHit.dataset.tile);}else{const hit=raw?.closest('[data-drop]');if(hit)moveRummiTile(dragData,hit.dataset.drop,+hit.dataset.group);}endTileDrag()};window.addEventListener('pointermove',dragMove);window.addEventListener('pointerup',dragUp,{once:true})}
function moveGhost(x,y){if(dragGhost){dragGhost.style.left=(x-22)+'px';dragGhost.style.top=(y-30)+'px'}}
function endTileDrag(){dragGhost?.remove();dragGhost=null;if(dragMove)window.removeEventListener('pointermove',dragMove);dragData=null;dragMove=null;dragUp=null}
function reorderRackTile(id,beforeId){const from=rDraft.rack.findIndex(t=>t.id===id),to=rDraft.rack.findIndex(t=>t.id===beforeId);if(from<0||to<0)return;const [t]=rDraft.rack.splice(from,1);const pos=rDraft.rack.findIndex(x=>x.id===beforeId);rDraft.rack.splice(Math.max(0,pos),0,t);renderRummi()}
function takeDraftTile(d){let tile;if(d.source==='rack'){const i=rDraft.rack.findIndex(t=>t.id===d.id);if(i>=0)tile=rDraft.rack.splice(i,1)[0]}else{const g=rDraft.board[d.group]||[],i=g.findIndex(t=>t.id===d.id);if(i>=0)tile=g.splice(i,1)[0];rDraft.board=rDraft.board.filter(g=>g.length)}return tile}
function moveRummiTile(d,dest,group){const tile=takeDraftTile(d);if(!tile)return;if(dest==='rack')rDraft.rack.push(tile);else if(dest==='new')rDraft.board.push([tile]);else{const g=rDraft.board[group];if(g)g.push(tile);else rDraft.board.push([tile]);}autoArrangeRummi();renderRummi()}
function autoArrangeRummi(){rDraft.board=rDraft.board.filter(g=>g.length).map(g=>{const non=g.filter(t=>!t.joker);if(non.length>1&&non.every(t=>t.n===non[0].n))return [...g].sort((a,b)=>a.color.localeCompare(b.color));if(non.length>1&&non.every(t=>t.color===non[0].color))return [...g].sort((a,b)=>(a.joker?99:a.n)-(b.joker?99:b.n));return g})}
function renderTimer(){clearInterval(tick);const e=$('#timer');if(!state.deadline){e.classList.add('hidden');return}e.classList.remove('hidden');const f=()=>{const n=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));e.textContent=Math.floor(n/60)+':'+String(n%60).padStart(2,'0');e.classList.toggle('urgent',n<=10);if(state.game==='rummi'&&state.phase==='rummiPlay'&&n<=10&&n>0){const key=`${state.rummi?.turnNumber}:${n}`;if(key!==lastRummiWarningKey){lastRummiWarningKey=key;playSfx('warning');if(n===10||n<=3)showEventPopup(`⏰ ${n}초 남았습니다!`,'rummi-warning',900)}}if(state.game==='stockwar'&&['stockInfoReview','stockNegotiation','stockAuction','stockTrade','stockResult'].includes(state.phase)&&n<=5&&n>0){const key=`${state.phase}:${state.stock?.round}:${n}`;if(key!==lastStockWarningKey){lastStockWarningKey=key;playSfx('warning');}}};f();tick=setInterval(f,250)}
$('#stockWhisperClose')?.addEventListener('click',()=>$('#stockWhisperModal')?.classList.add('hidden'));$('#stockRulesOpen')?.addEventListener('click',()=>openStockRules(0));$('#stockRulesClose')?.addEventListener('click',()=>$('#stockRulesModal')?.classList.add('hidden'));$('#stockRulesPrev')?.addEventListener('click',()=>{stockRulesModalPage=Math.max(0,stockRulesModalPage-1);renderStockRulesModal()});$('#stockRulesNext')?.addEventListener('click',()=>{stockRulesModalPage=Math.min(stockRulePages().length-1,stockRulesModalPage+1);renderStockRulesModal()});$('#stockMemoSide')?.addEventListener('input',e=>localStorage.setItem(stockMemoKey(),e.target.value));
$('#stockShopClose')?.addEventListener('click',()=>$('#stockShopModal')?.classList.add('hidden'));
function sendStockWhisper(){const text=$('#stockWhisperInput')?.value.trim();if(!stockChatTarget||!text)return;socket.emit('stockWhisper',{targetId:stockChatTarget,text},r=>{if(!r.ok)return toast(r.error);$('#stockWhisperInput').value='';setTimeout(()=>$('#stockWhisperInput')?.focus(),0)})}
$('#stockWhisperSend')?.addEventListener('click',sendStockWhisper);$('#stockWhisperInput')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();sendStockWhisper()}});
$('#stockTransferSend')?.addEventListener('click',()=>{const amount=+$('#stockTransferAmount')?.value||0;if(!stockChatTarget)return;socket.emit('stockTransferCoin',{targetId:stockChatTarget,amount},r=>{toast(r.ok?'코인을 보냈습니다.':r.error);if(r.ok)$('#stockTransferAmount').value=''})});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});

function applyAudioVolumes(){const v=bgmVolume();stockBgm.volume=v;vaultBgm.volume=v;geniusLobbyBgm.volume=v;[mafiaNightBgm,mafiaDayBgm,mafiaVoteBgm].forEach(a=>a.volume=v);mafiaGunSfx.volume=sfxVolume()}
function syncAudioSettingsUi(){const map=[['sfxToggle',soundOn],['bgmToggle',bgmOn],['narrationToggle',narrationOn],['voiceToggle',voiceOn]];map.forEach(([id,val])=>{const e=$('#'+id);if(e)e.checked=val});const vals=[['sfxVolume','sfxVolumeValue',clampAudio(localStorage.sosoSfxVolume,20)],['bgmVolume','bgmVolumeValue',clampAudio(localStorage.sosoBgmVolume,10)],['narrationVolume','narrationVolumeValue',clampAudio(localStorage.sosoNarrationVolume,85)],['voiceVolume','voiceVolumeValue',clampAudio(localStorage.sosoVoiceVolume,100)]];vals.forEach(([id,lid,val])=>{const e=$('#'+id),l=$('#'+lid);if(e)e.value=val;if(l)l.textContent=val+'%'})}
function refreshAudio(){applyAudioVolumes();syncStockAudio();syncMafiaAudio();syncGeniusAudio()}
$('#audioSettingsOpen')?.addEventListener('click',()=>{$('#audioSettingsModal')?.classList.remove('hidden');syncAudioSettingsUi()});
$('#audioSettingsClose')?.addEventListener('click',()=>$('#audioSettingsModal')?.classList.add('hidden'));
$('#audioSettingsModal')?.addEventListener('click',e=>{if(e.target.id==='audioSettingsModal')e.currentTarget.classList.add('hidden')});
$('#sfxToggle')?.addEventListener('change',e=>{soundOn=e.target.checked;localStorage.sosoSound=soundOn?'on':'off';if(soundOn)playSfx('start')});
$('#bgmToggle')?.addEventListener('change',e=>{bgmOn=e.target.checked;localStorage.sosoBgm=bgmOn?'on':'off';refreshAudio()});
$('#narrationToggle')?.addEventListener('change',e=>{narrationOn=e.target.checked;localStorage.sosoNarration=narrationOn?'on':'off';if(!narrationOn)try{speechSynthesis.cancel()}catch{}});
$('#voiceToggle')?.addEventListener('change',e=>{voiceOn=e.target.checked;localStorage.sosoVoice=voiceOn?'on':'off';if(!voiceOn)stopVoice();else if(voiceStream)syncVoicePeers();});
[['sfxVolume','sosoSfxVolume','sfxVolumeValue'],['bgmVolume','sosoBgmVolume','bgmVolumeValue'],['narrationVolume','sosoNarrationVolume','narrationVolumeValue'],['voiceVolume','sosoVoiceVolume','voiceVolumeValue']].forEach(([id,key,lid])=>$('#'+id)?.addEventListener('input',e=>{localStorage.setItem(key,e.target.value);const l=$('#'+lid);if(l)l.textContent=e.target.value+'%';refreshAudio()}));
// Genius voice rooms (WebRTC mesh, max 10 players)
let voiceStream=null,voicePeers=new Map(),voiceRoomCooldown=0,voiceSpeaking=false;
const voiceCfg={iceServers:[{urls:'stun:stun.l.google.com:19302'}]};
function voiceEligible(){return !!state&&['genius','stockwar','secretvault'].includes(state.game)}
function myVoiceRoom(){return state?.players?.find(p=>p.id===me)?.voiceRoom||'MAIN'}
async function startVoice(){if(!voiceEligible())return toast('지니어스게임에서 사용할 수 있습니다.');if(!voiceOn){voiceOn=true;localStorage.sosoVoice='on';syncAudioSettingsUi()}try{if(!voiceStream){voiceStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});setupVoiceMeter()}socket.emit('voiceJoin',{},r=>{if(!r?.ok)return toast(r?.error||'음성 연결 실패');toast('음성 연결됨');syncVoicePeers();renderVoiceRooms()})}catch(e){toast('마이크 권한을 허용해주세요.')}}
function stopVoice(){for(const pc of voicePeers.values())try{pc.close()}catch{}voicePeers.clear();if(voiceStream){voiceStream.getTracks().forEach(t=>t.stop());voiceStream=null}document.querySelectorAll('audio[data-voice-peer]').forEach(x=>x.remove());renderVoiceRooms()}
function setupVoiceMeter(){try{const c=ac(),src=c.createMediaStreamSource(voiceStream),an=c.createAnalyser();an.fftSize=256;src.connect(an);const arr=new Uint8Array(an.frequencyBinCount);const loop=()=>{if(!voiceStream)return;an.getByteFrequencyData(arr);const avg=arr.reduce((a,b)=>a+b,0)/arr.length;const on=avg>18;if(on!==voiceSpeaking){voiceSpeaking=on;document.querySelector(`[data-player-id="${me}"]`)?.classList.toggle('voice-speaking',on)}requestAnimationFrame(loop)};loop()}catch{}}
function peerAudio(id,stream){let a=document.querySelector(`audio[data-voice-peer="${id}"]`);if(!a){a=document.createElement('audio');a.autoplay=true;a.dataset.voicePeer=id;document.body.appendChild(a)}a.srcObject=stream;a.volume=voiceVolume();a.play().catch(()=>{})}
function closeVoicePeer(id){const pc=voicePeers.get(id);if(pc)try{pc.close()}catch{}voicePeers.delete(id);document.querySelector(`audio[data-voice-peer="${id}"]`)?.remove()}
async function ensureVoicePeer(id,offerer=false){if(!voiceStream||!voiceOn||id===me)return null;let pc=voicePeers.get(id);if(pc)return pc;pc=new RTCPeerConnection(voiceCfg);voicePeers.set(id,pc);voiceStream.getTracks().forEach(t=>pc.addTrack(t,voiceStream));pc.onicecandidate=e=>{if(e.candidate)socket.emit('voiceSignal',{targetId:id,data:{type:'ice',candidate:e.candidate}})};pc.ontrack=e=>peerAudio(id,e.streams[0]);pc.onconnectionstatechange=()=>{if(['failed','closed','disconnected'].includes(pc.connectionState))setTimeout(()=>{if(pc.connectionState!=='connected')closeVoicePeer(id)},1500)};if(offerer){const offer=await pc.createOffer();await pc.setLocalDescription(offer);socket.emit('voiceSignal',{targetId:id,data:{type:'sdp',description:pc.localDescription}})}return pc}
async function syncVoicePeers(){if(!voiceStream||!voiceOn||!voiceEligible())return;const room=myVoiceRoom(),wanted=new Set(state.players.filter(p=>p.id!==me&&p.connected&&!p.isBot&&(p.voiceRoom||'MAIN')===room).map(p=>p.id));for(const id of [...voicePeers.keys()])if(!wanted.has(id))closeVoicePeer(id);for(const id of wanted)if(!voicePeers.has(id)&&String(me)<String(id))await ensureVoicePeer(id,true)}
socket.on('voiceSignal',async m=>{if(!voiceStream||!voiceOn||!voiceEligible())return;const sender=state?.players?.find(p=>p.id===m.fromId);if(!sender||(sender.voiceRoom||'MAIN')!==myVoiceRoom())return;const pc=await ensureVoicePeer(m.fromId,false);try{if(m.data?.type==='sdp'){await pc.setRemoteDescription(m.data.description);if(m.data.description.type==='offer'){const ans=await pc.createAnswer();await pc.setLocalDescription(ans);socket.emit('voiceSignal',{targetId:m.fromId,data:{type:'sdp',description:pc.localDescription}})}}else if(m.data?.type==='ice'&&m.data.candidate)await pc.addIceCandidate(m.data.candidate)}catch{}});
function moveVoiceRoom(room){if(Date.now()<voiceRoomCooldown)return toast('방 이동은 3초마다 가능합니다.');voiceRoomCooldown=Date.now()+3000;socket.emit('voiceMove',{room},r=>{if(!r?.ok)return toast(r?.error||'이동할 수 없습니다.');setTimeout(syncVoicePeers,100);renderVoiceRooms()})}
function renderVoiceRooms(){const e=$('#voiceRoomsPanel');if(!e)return;if(!voiceEligible()){e.classList.add('hidden');return}e.classList.remove('hidden');const locked=state.game==='stockwar'&&['stockAuction','stockTrade'].includes(state.phase);const room=myVoiceRoom();const names=k=>state.players.filter(p=>p.connected&&!p.isBot&&(p.voiceRoom||'MAIN')===k).map(p=>esc(p.name)).join(' · ')||'비어있음';e.innerHTML=`<div class="voice-head"><b>VOICE ROOMS</b><small>${voiceStream?'연결됨':'마이크 미연결'}</small></div>${voiceStream?`<button class="voice-connect danger-soft" id="voiceDisconnect">음성 연결 끄기</button>`:`<button class="voice-connect primary" id="voiceConnect">음성 연결</button>`}<div class="voice-room-grid">${['MAIN','A','B','C'].map(k=>`<button class="voice-room ${room===k?'active':''}" data-voice-room="${k}" ${locked&&k!=='MAIN'?'disabled':''}><b>${k==='MAIN'?'MAIN ROOM':k+' ROOM'}</b><span>${names(k)}</span></button>`).join('')}</div>${locked?'<div class="voice-room-locked">경매·시장 거래 중에는 MAIN ROOM 전체 음성만 사용할 수 있습니다.</div>':''}<div class="voice-status">현재 위치 · <b>${room==='MAIN'?'MAIN ROOM':room+' ROOM'}</b> · 방 이동 쿨타임 3초</div>`;$('#voiceConnect')?.addEventListener('click',startVoice);$('#voiceDisconnect')?.addEventListener('click',stopVoice);$$('[data-voice-room]').forEach(b=>b.onclick=()=>moveVoiceRoom(b.dataset.voiceRoom));if(voiceStream)setTimeout(syncVoicePeers,0)}

// Persistent stock dealer Q&A
const dealerQaHistory=[];function openDealerQa(){if(state?.game!=='stockwar')return;$('#dealerQaModal')?.classList.remove('hidden');setTimeout(()=>$('#dealerQuestionGlobal')?.focus(),30)}function closeDealerQa(){$('#dealerQaModal')?.classList.add('hidden')}$('#stockDealerSide')?.addEventListener('click',openDealerQa);$('#dealerQaClose')?.addEventListener('click',closeDealerQa);function askGlobalDealer(){const input=$('#dealerQuestionGlobal'),q=input?.value.trim();if(!q)return;dealerQaHistory.push({who:'나',text:q});if(input)input.value='';renderDealerHistory();socket.emit('stockDealerAsk',{question:q},r=>{dealerQaHistory.push({who:'딜러',text:r.ok?r.answer:r.error});renderDealerHistory();setTimeout(()=>$('#dealerQuestionGlobal')?.focus(),0)})}function renderDealerHistory(){const e=$('#dealerQaHistory');if(!e)return;e.innerHTML=dealerQaHistory.slice(-20).map(x=>`<div class="dealer-chat-row ${x.who==='딜러'?'dealer':'user'}"><div class="dealer-chat-bubble"><b>${x.who}&nbsp;</b><span>${esc(x.text)}</span></div></div>`).join('');e.scrollTop=e.scrollHeight}$('#dealerAskGlobal')?.addEventListener('click',askGlobalDealer);$('#dealerQuestionGlobal')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();askGlobalDealer()}});
